{s:QZ,k:'pq',term:'Question 1',lv:'U',n:1,q:"What is an omnidirectional reflector?",say:'Question one. What is an omnidirectional reflector?',cues:{k:'Question one',q:'What is an'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 1',lv:'U',n:1,q:"What is an omnidirectional reflector?",say:'It is a multilayer stack with enough index contrast. It reflects a band of wavelengths at every angle of incidence. And it does so for both polarizations.',cues:{a1:'It is a',a2:'It reflects a',a3:'And it does'},al:[["A multilayer stack with enough index contrast",'a1'],["that reflects a band of wavelengths for all angles of incidence",'a2'],["and both polarizations.",'a3']],vis:(c,u,b)=>{
 const ys=330, P0=[[130,12,BLU],[290,36,ORG],[430,58,MAG]], L=220;
 let st='';for(let k=0;k<8;k++){st+=OF_rect(30,ys+k*16,560,7,OF_HI,'none')+OF_rect(30,ys+k*16+7,560,9,OF_LO,'none')}
 const ray=([px,th,col])=>{const s=Math.sin(OF_R(th)),co=Math.cos(OF_R(th));return OF_arrow(px-L*s,ys-L*co,px-1,ys-2,col,4)+OF_arrow(px,ys,px+L*s*0.55,ys-L*co*0.55,col,4)+OF_T(px-L*s,ys-L*co-12,`${th}°`,{fs:22,fw:800,a:'middle',fill:col})};
 return `${g('pop',tk(c,'a1'),st+OF_T(310,ys+156,'high-contrast multilayer stack',{fs:22,fw:800,a:'middle'}))}
${g('pop',tk(c,'a2'),ray(P0[0]))}${g('pop',tk(c,'a2')+0.5,ray(P0[1]))}${g('pop',tk(c,'a2')+1.0,ray(P0[2]))}
${g('rise',tk(c,'a3'),OF_T(600,40,'every angle, TE and TM: reflected',{fs:22,fw:800,a:'end',fill:GRN}))}`}},
{s:QZ,k:'pq',term:'Question 2',lv:'A',n:2,q:"A symmetric stack has t = 0.6 µm, n₁ = 1.48, n₂ = 1.46 at λ = 1.3 µm. Find V for the thickness and decide if it is single-mode.",say:'Question two. A symmetric stack, zero point six micrometers thick, has n one of one point four eight and n two of one point four six, at one point three micrometers. Find V across the thickness. Is it single-mode?',cues:{k:'Question two',q:'A symmetric stack'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 2',lv:'A',n:2,q:"A symmetric stack has t = 0.6 µm, n₁ = 1.48, n₂ = 1.46 at λ = 1.3 µm. Find V for the thickness and decide if it is single-mode.",say:`Same recipe. The squares differ by zero point zero five eight eight, so the ${P('NA')} is zero point two four two five. Two pi t over lambda is two point nine. V is zero point seven zero three: below pi, single-mode.`,cues:{fk:'Same recipe',k1:'The squares differ',k1b:'so the',k2:'Two pi t',k3:'V is zero',k3b:'below pi, single-mode'},calc:{f:['V = (2πt / λ) √(n₁² − n₂²)','single-mode if V < π'],hint:'The same steps as the first worked example.',fk:'fk',steps:[["Index step",["1.48² − 1.46² = 2.1904 − 2.1316 = 0.0588","NA = √0.0588 = 0.2425"],["k1","k1b"]],["Size term","2π × 0.6 / 1.3 = 2.900","k2"],["V",["V = 2.900 × 0.2425 = 0.703","V = 0.703 < π: single-mode"],["k3","k3b"]]],live:[0,1,2]}},
{s:QZ,k:'pq',term:'Question 3',lv:'N',n:3,q:"A guide has V = 0.7 across its thickness but is 8 µm wide, with the lateral step of the second worked example (0.1364, at λ = 1.55 µm). Is it single-mode?",say:`Question three. A guide has V of zero point seven across its thickness, but is eight micrometers wide, with the second worked example's lateral step. Is it single-mode?`,cues:{k:'Question three',q:'A guide has'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 3',lv:'N',n:3,q:"A guide has V = 0.7 across its thickness but is 8 µm wide, with the lateral step of the second worked example (0.1364, at λ = 1.55 µm). Is it single-mode?",say:'No. The thickness passes, but the width fails. The lateral V is two pi times eight over one point five five, times zero point one three six four: four point four two, above pi. So a second lateral mode is guided.',cues:{a1:'The thickness passes',a2:'The lateral V',a2b:'four point four two',a3:'So a second'},al:[["No: the thickness passes, but the width fails.",'a1'],["Lateral V = (2π × 8 / 1.55) × 0.1364 = 4.42 > π",'a2'],["A second lateral mode is guided; single-mode only below about 5.7 µm.",'a3']],vis:(c,u,b)=>{
 const X=w=>70+w*52, Y=v=>420-v*60;
 const ax=OF_L(70,420,600,420,'#18213A',3)+OF_L(70,420,70,50,'#18213A',3)+[0,2,4,6,8,10].map(w=>OF_T(X(w),450,String(w),{fs:22,a:'middle',fill:OF_GREY})).join('')+[0,2,4,6].map(v=>OF_T(58,Y(v)+8,String(v),{fs:22,a:'end',fill:OF_GREY})).join('')+OF_T(600,484,'width w (µm)',{fs:22,fw:700,a:'end',fill:OF_GREY})+OF_T(84,64,'lateral V',{fs:22,fw:700,fill:OF_GREY});
 const pts=[];for(let w=0;w<=10.001;w+=0.5)pts.push(`${X(w).toFixed(1)},${Y(OF_VW(w)).toFixed(1)}`);
 return `${g('pop',tk(c,'a1'),ax+OF_rect(70,Y(Math.PI),530,420-Y(Math.PI),GRN,'none',0,'fill-opacity=".12"')+OF_L(70,Y(Math.PI),600,Y(Math.PI),GRN,3,'stroke-dasharray="8 6"')+OF_T(84,Y(Math.PI)-12,'π: one lateral mode below',{fs:22,fw:800,fill:GRN})+`<polyline points="${pts.join(' ')}" fill="none" stroke="${BLU}" stroke-width="4"/>`+`<circle cx="${X(2)}" cy="${Y(OF_VW(2)).toFixed(1)}" r="9" fill="${GRN}"/>`+OF_T(X(2)+16,Y(OF_VW(2))+28,'2 µm: 1.11',{fs:22,fw:800,fill:GRN}))}
${g('pop',tk(c,'a2b'),`<circle cx="${X(8)}" cy="${Y(OF_VW(8)).toFixed(1)}" r="10" fill="${MAG}"/>`+OF_T(X(8)-14,Y(OF_VW(8))-16,'8 µm: 4.42',{fs:22,fw:800,a:'end',fill:MAG}))}
${g('pop',tk(c,'a3'),OF_L(X(OF_WMAX),Y(Math.PI),X(OF_WMAX),420,ORG,3)+OF_T(X(OF_WMAX)+10,404,'5.7 µm',{fs:22,fw:800,fill:ORG}))}`}},
{s:LS,k:'figs',term:'Your notes',title:'For your notes',say:'Your free notes are the PDF linked in the description. Redraw the guide with its two checks, and the stop band of the mirror.',cues:{t:'Your free notes',f:'Redraw the guide'},tags:[["Free notes for this lesson (PDF)", "link in the description"], ["In this lesson", "Integrated optical waveguides: strip and channel; Photonic crystals and photonic band gap"], ["Key terms and glossary", "at the end of the notes"]],figs:[["The buried channel guide and its two checks", "A 2 µm × 0.5 µm core (n₁ = 1.50) in n₂ = 1.45: the thickness gives V = 0.778 and a mode index of 1.4564; against the sides that gives V = 1.11, so the guide is single-mode."], ["The Bragg mirror's stop band", "8 quarter-wave pairs of silicon nitride and silica on silica: inside the 1407 to 1726 nm band light cannot pass, and R reaches 98.4 % at 1550 nm."]],note:"Sources your free notes draw on: Gerd Keiser (waveguiding and fabrication); John M. Senior (electromagnetic mode theory and fiber types); Govind P. Agrawal (wave propagation and dispersion)"},
{s:OUT,k:'outro',term:'Outro',say:'So remember: thickness first, then width. A Bragg period is one full pair of layers. And a band gap is a band, not a line. Next time, attenuation in optical fibers. See you there!',cues:{f:'So remember',w1:'thickness first',w2:'period is one',w3:'And a band gap',n:'Next time',s:'See you there'},words:[['THICKNESS, THEN WIDTH','BLU','w1'],['ONE PERIOD = ONE PAIR','ORG','w2'],['A BAND, NOT A LINE','GRN','w3']],next:["NEXT TIME", "Next lesson", "Attenuation in optical fibers", "book"],end:'See you there!'}
